input.command:
$7z = 'D:\Program Files\7-Zip\7z.exe'
$in = 'AGENTS.md'
$orig = (Get-Item -LiteralPath $in).Length
Get-ChildItem -LiteralPath build -Filter 'p2_*' -ErrorAction SilentlyContinue | Remove-Item -Force

$cases = @(
  @{ label='zip -mx=1'; out='build\p2_zip1.zip'; type='-tzip'; mx='-mx=1' },
  @{ label='zip -mx=9'; out='build\p2_zip9.zip'; type='-tzip'; mx='-mx=9' },
  @{ label='7z -mx=1';  out='build\p2_7z1.7z';  type='-t7z';  mx='-mx=1' },
  @{ label='7z -mx=9';  out='build\p2_7z9.7z';  type='-t7z';  mx='-mx=9' }
)

"ORIGINAL: $in = $orig bytes"
""
foreach ($c in $cases) {
  $cmd = "& '$7z' a $($c.type) $($c.mx) $($c.out) $in"
  "COMMAND: $cmd"
  $tc = Measure-Command { & $7z a $c.type $c.mx $c.out $in | Out-Null }
  "  compress  : {0,8:N0} ms" -f $tc.TotalMilliseconds
}
""
foreach ($c in $cases) {
  $td = Measure-Command { & $7z t $c.out | Out-Null }
  "DECOMPRESS {0,-10}: {1,8:N0} ms" -f $c.label, $td.TotalMilliseconds
}
""
"RESULTS (ratio = Packed / Original):"
foreach ($c in $cases) {
  $l = (& $7z l -slt $c.out) -join "`n"
  $packed = [int]([regex]::Match($l, 'Packed Size = (\d+)').Groups[1].Value)
  $phys = [int]([regex]::Match($l, 'Physical Size = (\d+)').Groups[1].Value)
  $method = [regex]::Match($l, 'Method = (.+)').Groups[1].Value.Trim()
  $ratio = $packed / $orig
  "{0,-10}  Packed={1,8}  Physical={2,8}  ratio={3:N4}  Method={4}" -f $c.label, $packed, $phys, $ratio, $method
}

