input.command:
$root = 'C:\Users\User\Desktop\inobitec_stud'
$cands = @('t1_dist_matrix_c','t3_bbox_c','t4_filter_c','tests\unit','tests\expect','notes','common','gen_cloud')
foreach ($c in $cands) {
  $p = Join-Path $root $c
  if (Test-Path -LiteralPath $p) {
    $f = Get-ChildItem -LiteralPath $p -Recurse -File -ErrorAction SilentlyContinue
    "{0,-16} files={1,4}  total={2,9} B" -f $c, $f.Count, (($f | Measure-Object Length -Sum).Sum)
  } else { "{0,-16} MISSING" -f $c }
}

