input.command:
'=== build\1.txt ==='
Get-Content -LiteralPath 'build\1.txt'
''
'=== build\2.txt ==='
Get-Content -LiteralPath 'build\2.txt'
''
foreach ($f in 'build\3.txt','build\4.txt') {
  "=== $f : header + block structure ==="
  $c = Get-Content -LiteralPath $f
  $c | Where-Object { $_ -match '^(Solid|Blocks|Physical Size|Headers Size) =' }
  $blocks = $c | Where-Object { $_ -match '^Block = ' } | ForEach-Object { ($_ -split '=',2)[1].Trim() }
  "distinct Block values: " + (($blocks | Select-Object -Unique) -join ', ')
  "Block lines count: " + $blocks.Count
  $pk = $c | Where-Object { $_ -match '^Packed Size = ' } | ForEach-Object { [int](($_ -split '=',2)[1].Trim()) }
  if ($pk) { "sum Packed: $((($pk) | Measure-Object -Sum).Sum)" } else { "no per-file Packed Size lines (single-stream?)" }
}

